-- REQ-e11b477a：系统集成官方API接口目录（表 + 禅道/Jenkins 种子；GitLab 种子在后续迁移）。
-- 种子由需求目录 生成脚本/generate_api_catalog.py 产出（来源清单见 种子/来源清单.json）。
-- 幂等：INSERT 均带 WHERE NOT EXISTS（键：system_code + resource_group + http_method + api_path）。

CREATE TABLE IF NOT EXISTS `sys_integration_api_endpoint` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `system_code` VARCHAR(64) NOT NULL COMMENT '集成系统编码：ZENTAO/JENKINS/GITLAB',
  `resource_group` VARCHAR(128) NOT NULL COMMENT '官方资源组/模块标识',
  `resource_group_name` VARCHAR(256) DEFAULT NULL COMMENT '资源组显示名',
  `api_name` VARCHAR(512) NOT NULL COMMENT '官方接口名称',
  `http_method` VARCHAR(16) NOT NULL COMMENT 'HTTP 方法：GET/POST/PUT/DELETE/PATCH',
  `api_path` VARCHAR(1024) NOT NULL COMMENT '请求路径模板（占位符统一 {name} 形式）',
  `summary` VARCHAR(2048) DEFAULT NULL COMMENT '官方说明摘录',
  `platform_used` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '平台已调用标记（与 WorkHub 调用点对齐）',
  `source_url` VARCHAR(1024) DEFAULT NULL COMMENT '来源文档页',
  `source_note` VARCHAR(512) DEFAULT NULL COMMENT '来源口径备注',
  `sort_order` INT NOT NULL DEFAULT 0 COMMENT '排序',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_api_catalog_group` (`system_code`, `resource_group`, `sort_order`),
  KEY `idx_api_catalog_method` (`system_code`, `http_method`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统集成官方API接口目录';

